// Loop hasta cubrir todas las guías no-terminales: la masiva Urbano tarda ~0.3s/código,
// cada invocación procesa 100 (~43s, entra en el timeout de Vercel). ceil(total/100) llamadas.
const BASE = $env.VERCEL_URL || 'https://biolabs-finanzas.vercel.app';
const hdr = { Authorization: 'Bearer ' + $env.CRON_SECRET };
let r = await this.helpers.httpRequest({ method: 'POST', url: BASE + '/api/sync/urbano?limit=100', headers: hdr, json: true });
const total = r.total || 0;
let done = r.processed || 0;
const loops = Math.max(0, Math.ceil(total / 100) - 1);
for (let i = 0; i < loops; i++) {
  r = await this.helpers.httpRequest({ method: 'POST', url: BASE + '/api/sync/urbano?limit=100', headers: hdr, json: true });
  done += r.processed || 0;
}
return [{ json: { total, invocaciones: loops + 1, procesadas: done } }];
